<?php
require_once __DIR__.'/../includes/init.php';
require_roles(['super_admin','principal','admin_officer']);
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if($id>0&&in_array($status,['new','read','closed'],true)){$s=$pdo->prepare('UPDATE contact_messages SET status=? WHERE id=?');$s->execute([$status,$id]);flash('Enquiry status updated.');}go('admin/contact_messages.php');}
$rows=$pdo->query('SELECT * FROM contact_messages ORDER BY created_at DESC')->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Contact Enquiries</title><link rel="stylesheet" href="<?= BASE_URL ?>/assets/css/app.css"></head><body><?php require __DIR__.'/../includes/header.php'; ?><main class="main"><section class="panel"><h1>Public Website Enquiries</h1><p>Messages submitted using the public Contact form.</p><?php show_flash(); ?><div style="overflow:auto"><table><thead><tr><th>Received</th><th>Name / Contact</th><th>Subject</th><th>Message</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= h($r['created_at']) ?></td><td><?= h($r['name']) ?><br><?= h($r['phone']) ?><br><?= h($r['email']) ?></td><td><?= h($r['subject']) ?></td><td><?= nl2br(h($r['message'])) ?></td><td><?= h($r['status']) ?></td><td><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf()) ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><select name="status"><?php foreach(['new','read','closed'] as $st): ?><option value="<?= h($st) ?>" <?= $r['status']===$st?'selected':'' ?>><?= h(ucfirst($st)) ?></option><?php endforeach; ?></select><button class="btn" style="margin-top:5px">Save</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6">No enquiries received yet.</td></tr><?php endif; ?></tbody></table></div></section></main><?php require __DIR__.'/../includes/footer.php'; ?></body></html>
